#include <bits/stdc++.h>
using namespace std;

#define int long long
const int MAXN = 1000005;
int modAlpha = 998244353, modBeta = 1e9 + 7;
int st[15];
string good[MAXN];
int N, number;
vector<string> lenn[7];
vector<int> ok[7][7];
int sum[7][7];

inline int goal(const string& s) {
    int res = 0;
    for (auto c : s) res = res * 10 + c - '0';
    return res;
}

__int128 evaluate(const string& s, int max_len) {
    if (max_len == -1) return 0;
    int L = max_len / 2, R = max_len - L;
    if (max_len == 1) L = 1, R = 0;
    __int128 res = (number - goal(s) + modAlpha * modAlpha) % modAlpha;
    number++;
    for (auto prefix : lenn[L]) {
        res += (-goal(s + prefix) + number + modAlpha * modAlpha) % modAlpha;
        number++;
        if ((int)prefix.size() == L) {
            int c = goal(s + prefix) % modAlpha;
            for (int oth = 1; oth <= R; ++oth) {
                int cnst = (-c * st[oth] + number + modAlpha * modAlpha) % modAlpha;
                int idx = lower_bound(ok[R][oth].begin(), ok[R][oth].end(), modAlpha - cnst) - ok[R][oth].begin();
                res += (int)ok[R][oth].size() * cnst + sum[R][oth] - modAlpha * ((int)ok[R][oth].size() - idx);
            }
            number += (int)lenn[R].size();
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    N = (int)to_string(n).size();
    st[0] = 1;
    for (int i = 1; i <= 14; ++i) st[i] = st[i - 1] * 10;
    string s = to_string(n);
    string cur = "";
    for (int i = 0; i < MAXN; ++i) {
        good[i] = to_string(i);
        string now = good[i];
        while ((int)now.size() <= 6) {
            lenn[(int)now.size()].push_back(now);
            now = "0" + now;
        }
    }
    for (int i = 1; i <= 6; ++i) {
        for (auto key : lenn[i - 1]) lenn[i].push_back(key);
        sort(lenn[i].begin(), lenn[i].end());
        for (int j = 0; j < (int)lenn[i].size(); ++j) {
            ok[i][lenn[i][j].size()].push_back((j - stoi(lenn[i][j]) + modAlpha) % modAlpha);
        }
        for (int j = 1; j <= i; ++j) {
            sort(ok[i][j].begin(), ok[i][j].end());
            for (auto key : ok[i][j]) sum[i][j] += key;
        }
    }
    vector<pair<string, int>> Q;
    for (int i = 0; i < (int)s.size(); ++i) {
        for (int j = 0; j <= 9; ++j) {
            if (j == s[i] - '0') continue;
            if (i == 0 && j == 0) continue;
            cur += char('0' + j);
            if (j <= s[i] - '0') {
                Q.emplace_back(cur, (int)s.size() - i - 1);
            } else {
                Q.emplace_back(cur, (int)s.size() - i - 2);
            }
            cur.pop_back();
        }
        cur += s[i];
        Q.emplace_back(cur, 0);
    }
    number = 1;
    __int128 ans = 0;
    sort(Q.begin(), Q.end());
    for (auto& key : Q) {
        if (s[(int)key.first.size() - 1] == key.first.back()) {
            ans += (-goal(key.first) + number + modAlpha * modAlpha) % modAlpha;
            number++;
            continue;
        }
        ans += evaluate(key.first, key.second);
    }
    ans %= modBeta;
    cout << (long long)ans;
    return 0;
}
